schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/fitness-function-suite-bootstrap.json",
  "title": "Starter fitness-function suite spec",
  "type": "object",
  "required": ["suite_id", "system", "owner", "dependency_graph", "launch_date", "weekly_reviews", "cadence_after_week_four", "functions"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "suite_id": {"type": "string", "pattern": "^ffsb-[a-z0-9]+(-[a-z0-9]+)*$"},
    "system": {"type": "string", "minLength": 2},
    "owner": {"$ref": "#/definitions/handle"},
    "dependency_graph": {
      "type": "object",
      "required": ["layers", "allowed_edges"],
      "additionalProperties": false,
      "properties": {
        "layers": {"type": "array", "minItems": 2, "items": {"type": "string", "minLength": 1}},
        "allowed_edges": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["from", "to"],
            "additionalProperties": false,
            "properties": {"from": {"type": "string", "minLength": 1}, "to": {"type": "string", "minLength": 1}}
          }
        }
      }
    },
    "launch_date": {"$ref": "#/definitions/date"},
    "weekly_reviews": {
      "type": "array",
      "minItems": 4,
      "maxItems": 4,
      "items": {
        "type": "object",
        "required": ["date", "reviewed_by", "red_functions", "actions"],
        "additionalProperties": false,
        "properties": {
          "date": {"$ref": "#/definitions/date"},
          "reviewed_by": {"$ref": "#/definitions/handle"},
          "red_functions": {"type": "array", "items": {"type": "string"}},
          "actions": {"type": "array", "items": {"type": "string", "minLength": 4}}
        }
      }
    },
    "cadence_after_week_four": {"type": "string", "enum": ["monthly", "quarterly"]},
    "functions": {
      "type": "array",
      "minItems": 5,
      "maxItems": 8,
      "allOf": [
        {"contains": {"properties": {"category": {"const": "performance"}}}},
        {"contains": {"properties": {"category": {"const": "deployability"}}}},
        {"contains": {"properties": {"category": {"const": "dependency"}}}},
        {"contains": {"properties": {"category": {"const": "complexity"}}}},
        {"contains": {"properties": {"category": {"const": "contract"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["id", "category", "tool", "command", "threshold", "baseline", "mode", "runs_on", "owner", "consecutive_red_reviews"],
        "additionalProperties": false,
        "properties": {
          "id": {"type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"},
          "category": {"type": "string", "enum": ["performance", "deployability", "dependency", "complexity", "contract"]},
          "tool": {"type": "string", "minLength": 2},
          "command": {"type": "string", "minLength": 4},
          "threshold": {
            "type": "object",
            "required": ["operator", "value", "unit"],
            "additionalProperties": false,
            "properties": {
              "operator": {"type": "string", "enum": ["<", "<=", ">", ">=", "=="]},
              "value": {"type": "number"},
              "unit": {"type": "string", "minLength": 1}
            }
          },
          "baseline": {
            "type": "object",
            "required": ["value", "measured_at"],
            "additionalProperties": false,
            "properties": {"value": {"type": "number"}, "measured_at": {"$ref": "#/definitions/date"}}
          },
          "mode": {"type": "string", "enum": ["informational", "ratchet", "blocking"]},
          "runs_on": {"type": "string", "enum": ["pull_request", "post_merge", "nightly"]},
          "owner": {"$ref": "#/definitions/handle"},
          "consecutive_red_reviews": {"type": "integer", "minimum": 0},
          "action": {"type": "string", "enum": ["fix", "rebaseline", "remove"]},
          "promotion": {
            "type": "object",
            "required": ["green_runs_on_main", "approved_by", "review_date", "promoted_at"],
            "additionalProperties": false,
            "properties": {
              "green_runs_on_main": {"type": "integer", "minimum": 5},
              "approved_by": {"$ref": "#/definitions/handle"},
              "review_date": {"$ref": "#/definitions/date"},
              "promoted_at": {"$ref": "#/definitions/date"}
            }
          },
          "endpoint": {"type": "string", "minLength": 2},
          "load_profile": {"type": "string", "minLength": 4},
          "runner_kind": {"type": "string", "enum": ["dedicated-runner", "dedicated-environment"]},
          "metric": {"type": "string", "enum": ["pipeline_duration", "merge_to_production_lead_time"]},
          "script_path": {"type": "string", "minLength": 4},
          "per_function_limit": {"type": "integer", "minimum": 1, "default": 10},
          "baseline_file": {"type": "string", "minLength": 4},
          "method": {"type": "string", "enum": ["pact", "schema-diff"]},
          "consumers": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}},
          "released_schema_ref": {"type": "string", "minLength": 4}
        },
        "allOf": [
          {"if": {"properties": {"mode": {"const": "blocking"}}}, "then": {"required": ["promotion"]}},
          {"if": {"properties": {"consecutive_red_reviews": {"minimum": 2}}}, "then": {"required": ["action"]}},
          {"if": {"properties": {"category": {"const": "performance"}}},
           "then": {"required": ["endpoint", "load_profile", "runner_kind"], "properties": {"runs_on": {"enum": ["post_merge", "nightly"]}}}},
          {"if": {"properties": {"category": {"const": "deployability"}}},
           "then": {"required": ["metric", "script_path"], "properties": {"threshold": {"properties": {"unit": {"const": "minutes"}}}}}},
          {"if": {"properties": {"category": {"const": "dependency"}}},
           "then": {"properties": {"tool": {"enum": ["ArchUnit", "NetArchTest", "dependency-cruiser", "import-linter"]}, "runs_on": {"const": "pull_request"}}}},
          {"if": {"properties": {"category": {"const": "complexity"}}},
           "then": {"required": ["per_function_limit", "baseline_file"], "properties": {"tool": {"enum": ["radon", "lizard", "eslint-complexity", "SonarQube"]}}}},
          {"if": {"properties": {"category": {"const": "contract"}}},
           "then": {"required": ["method"], "properties": {"tool": {"enum": ["Pact", "oasdiff", "openapi-diff", "buf"]}}, "anyOf": [{"required": ["consumers"]}, {"required": ["released_schema_ref"]}]}}
        ]
      }
    }
  }
}
